if(items){shell.append(node('p','workspace-meta','本次返回 '+items.length+' 条结果'+(op.partial?' · 有界预览，条目或摘要可能省略':'')));const list=node('div','ws-web-results');
for(const [index,raw] of items.entries()){const item=workspaceObject(raw),card=node('article','ws-web-result');card.append(node('h4','',(index+1)+'. '+(workspaceText(item.title)||'未提供标题')));if(workspaceText(item.url))card.append(node('div','browser-address',workspaceText(item.url)));card.append(node('p','',workspaceText(item.snippet)||'本条未返回摘要。'));list.append(card);}shell.append(list);if(!items.length)shell.append(node('p','workspace-inline-note','本次搜索没有返回结果。'));}
